/bin/bash -lc "python3 - <<'PY'
from PIL import Image
import numpy as np, cv2
im=np.asarray(Image.open('first_frame.png').convert('RGB'))
f=im.astype(float); gray=cv2.cvtColor(im,cv2.COLOR_RGB2GRAY)
# patch means at regular grid, each 20x20
for y in range(20,720,20):
 vals=[]
 for x in range(20,1280,20):
  p=f[y-10:y+10,x-10:x+10]
  vals.append((p.mean(),p.std(),x,y))
 # brightest local maxima nonoverlap
 vals.sort(reverse=True,key=lambda z:z[0])
 if y in [60,100,140,180,220,260,300,340,380,420,460,500,540,580,620,660,700]:
  print('y',y,[(round(v[0],1),v[2],v[3]) for v in vals[:4]])
# biggest dark lines around 0-200 region coords
for y in range(0,300,10):
 p=gray[y:y+10].mean(0)
 mins=[]
 for x in range(0,1280,10):
  if p[x:x+10].mean()<60: mins.append(x)
 # groups
 groups=[]
 for x in mins:
  if not groups or x>groups[-1][-1]+10: groups.append([x])
  else: groups[-1].append(x)
 if groups: print(y,[(g[0],g[-1]+10) for g in groups])
PY"
